package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.stats.*;
public final class DiagramModelsChecks {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Diagram model check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid model diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    static Node node(String id,ElementType type,String label,String... columns){JsonObject properties=new JsonObject();if(type.observed())properties.addProperty("column",columns[0]);else if(columns.length>0){JsonArray values=new JsonArray();for(String name:columns)values.add(name);properties.add("columns",values);}return new Node(id,type,label,100,100,properties);}
    static Link link(String id,ElementType type,String a,String b){return new Link(id,type,a,b,new JsonObject());}
    static Node anchor(String id,String edge){JsonObject properties=new JsonObject();properties.addProperty("edge",edge);return new Node(id,ElementType.DONGLE,"",0,0,properties);}
    static Document pls(){return new Document(1,Family.PLS,"root",List.of(node("root",ElementType.ROOT,"Model"),node("x",ElementType.LATENT_VARIABLE,"X","X1","X2"),node("w",ElementType.LATENT_VARIABLE,"W","W1","W2"),node("z",ElementType.LATENT_VARIABLE,"Z","Z1","Z2"),node("y",ElementType.LATENT_VARIABLE,"Y","Y1","Y2")),List.of(link("xy",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"x","y")),List.of());}
    public static void main(String[] args)throws Exception{
        List<String> names=List.of("X1","X2","W1","W2","Z1","Z2","Y1","Y2");var base=pls();var compiled=DiagramModels.pls(base,names);check(compiled.blocks().size()==4);check(Arrays.equals(compiled.blocks().get(0).columns(),new int[]{0,1}));check(compiled.edges().equals(List.of(new PlsSem.Edge(0,3))));check(compiled.extensions().isEmpty());
        var interaction=base.with(anchor("xy_anchor","xy")).with(link("xw",ElementType.CONNECTION_FOR_PLS_MODERATION,"w","xy_anchor")).with(anchor("xw_anchor","xw")).with(link("xwz",ElementType.CONNECTION_FOR_PLS_MODERATION,"z","xw_anchor")).with(node("quadratic",ElementType.QUADRATIC_EFFECT,"X squared")).with(link("square",ElementType.CONNECTION_BETWEEN_QUADRATIC_EFFECT_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"quadratic","xy_anchor"));var nonlinear=DiagramModels.pls(interaction,names);check(nonlinear.extensions().size()==3);check(Arrays.equals(nonlinear.extensions().get(0).factors(),new int[]{0,1}));check(Arrays.equals(nonlinear.extensions().get(1).factors(),new int[]{0,1,2}));check(Arrays.equals(nonlinear.extensions().get(2).factors(),new int[]{0,0}));check(nonlinear.edges().containsAll(List.of(new PlsSem.Edge(1,3),new PlsSem.Edge(2,3))));check(nonlinear.warnings().size()==2);
        JsonObject options=new JsonObject();options.addProperty("method","TWO_STAGE_GAUSSIAN");var gc=base.with(link("wy",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"w","y")).with(anchor("anchor","xy")).with(new Node("gc",ElementType.GAUSSIAN_COPULA,"GC",50,50,options)).with(link("gc_link",ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"gc","anchor"));var corrected=DiagramModels.pls(gc,names);check(corrected.copulas().size()==1&&corrected.copulas().getFirst().target()==3);check(Arrays.equals(corrected.copulas().getFirst().endogenous(),new int[]{0}));check(corrected.copulas().getFirst().method()==CopulaRegression.Method.TWO_STAGE_GAUSSIAN);
        Random random=new Random(451);double[][] data=new double[100][8];for(var row:data){double x=random.nextGaussian(),w=random.nextGaussian(),z=random.nextGaussian(),y=.6*x+.2*w+.2*z+.4*x*w+.25*x*w*z+.2*x*x+.4*random.nextGaussian();double[] values={x,w,z,y};for(int j=0;j<4;j++){row[2*j]=values[j]+.1*random.nextGaussian();row[2*j+1]=values[j]+.1*random.nextGaussian();}}var specification=new NonlinearPls.Specification(nonlinear.extensions(),List.of(new PathProcess.Probe("At means",Map.of())),new NonlinearPls.Grid(0,3,-1,1,11));var fit=NonlinearPls.fit(data,nonlinear.blocks(),nonlinear.edges(),PlsSem.Options.defaults(),specification);var renamed=interaction.with(interaction.node("x").named("Renamed X")).move(Set.of("x","y","w"),200,-30);var renamedInput=DiagramModels.pls(renamed,names);var unchanged=NonlinearPls.fit(data,renamedInput.blocks(),renamedInput.edges(),PlsSem.Options.defaults(),specification);check(Arrays.deepEquals(fit.firstStage().scores(),unchanged.firstStage().scores()));for(int i=0;i<fit.equations().size();i++)check(Arrays.equals(fit.equations().get(i).coefficients(),unchanged.equations().get(i).coefficients()));
        var generalized=new Document(1,Family.GSCA,"root",List.of(node("root",ElementType.ROOT,"Model"),node("a",ElementType.GSCA_LATENT_VARIABLE,"A"),node("b",ElementType.GSCA_LATENT_VARIABLE,"B"),node("v1",ElementType.GSCA_STANDARD_MANIFEST_VARIABLE,"Label 1","X1"),node("v2",ElementType.GSCA_STANDARD_MANIFEST_VARIABLE,"Label 2","X2"),node("v3",ElementType.GSCA_STANDARD_MANIFEST_VARIABLE,"Label 3","W1")),List.of(link("av1",ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_MV,"a","v1"),link("av2",ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_MV,"a","v2"),link("bv2",ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_MV,"b","v2"),link("bv3",ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_MV,"b","v3"),link("ab",ElementType.GSCA_CONNECTION_BETWEEN_LV_AND_LV,"a","b")),List.of());var gsca=DiagramModels.gsca(generalized,names);check(gsca.prepared().model().indicators().equals(List.of("X1","X2","W1")));check(gsca.prepared().model().weights()[1][0]&&gsca.prepared().model().weights()[1][1]);
        var regression=new Document(1,Family.REGRESSION,"root",List.of(node("root",ElementType.ROOT,"Model"),node("x",ElementType.REGRESSION_INDEPENDENT_VARIABLE,"Renamed predictor","W1"),node("y",ElementType.REGRESSION_DEPENDENT_VARIABLE,"Outcome","Y1"),node("constant",ElementType.REGRESSION_INTERCEPT,"Intercept")),List.of(link("predictor",ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INDEPENDENT_VARIABLE,"y","x"),link("intercept",ElementType.CONNECTION_BETWEEN_DEPENDENT_AND_INTERCEPT,"constant","y")),List.of());var selection=DiagramModels.regression(regression,names);check(selection.response()==6&&Arrays.equals(selection.predictors(),new int[]{2})&&selection.intercept());check(!DiagramModels.regression(regression.remove(Set.of("constant")),names).intercept());
        JsonObject fixed=new JsonObject();fixed.addProperty("free",false);reject(()->DiagramModels.pls(base.with(new Link("xy",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"x","y",fixed)),names));reject(()->DiagramModels.pls(base.with(link("yx",ElementType.CONNECTION_BETWEEN_LV_AND_LV,"y","x")),names));reject(()->DiagramModels.pls(base,List.of("Missing")));reject(()->DiagramModels.pls(base.with(node("empty",ElementType.LATENT_VARIABLE,"No indicators")),names));var allCorrected=gc.with(new Node("gc_w",ElementType.GAUSSIAN_COPULA,"GC W",0,0,options)).with(anchor("wy_anchor","wy")).with(link("gc_w_link",ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"gc_w","wy_anchor"));reject(()->DiagramModels.pls(allCorrected,names));
        Path output=Path.of(args[0]);Files.createDirectories(output);var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject evidence=new JsonObject();evidence.add("diagram",interaction.json());evidence.add("observations",gson.toJsonTree(data));evidence.add("compiled",gson.toJsonTree(nonlinear));evidence.add("fit",gson.toJsonTree(fit));Files.writeString(output.resolve("compiled-cases.json"),gson.toJson(evidence));System.out.println("{\"checks\":"+checks+",\"families\":3}");
    }
}
